import XCTest
// Каркас FeatureSupport.swift; validatedSupplies и SupplyRepository из урока.
final class InvalidCacheTests: XCTestCase {
    func testDuplicateCacheRejected() async {
        let cache = MemorySupplyCache(items: [
            Supply(id: 11, title: "Чай", count: 1),
            Supply(id: 11, title: "Чай", count: 2)
        ])
        let repository = SupplyRepository(
            cache: cache, remote: FixedSupplyRemote(items: [])
        )
        do {
            _ = try await repository.cached()
            XCTFail("Ожидался отказ повреждённого смысла данных")
        } catch { XCTAssertEqual(error as? SupplyError, .invalidData) }
    }
}

Синтаксически корректное хранение не доказывает доменный контракт. Ошибка появляется на границе Repository до показа в UI.

import XCTest
// Каркас FeatureSupport.swift; слои SupplyRepository из урока.
final class WriteFailCache: SupplyCache {
    let old = [Supply(id: 11, title: "Чай", count: 2)]
    func load() throws -> [Supply] { old }
    func save(_ values: [Supply]) throws { throw SupplyError.writeFailed }
}
final class CommitTests: XCTestCase {
    func testNoSuccessAfterWriteFailure() async throws {
        let cache = WriteFailCache()
        let repository = SupplyRepository(cache: cache,
            remote: FixedSupplyRemote(items: [
                Supply(id: 11, title: "Чай", count: 3)
            ]))
        do {
            _ = try await repository.refresh()
            XCTFail("Запись обязана подтвердиться")
        } catch { XCTAssertEqual(error as? SupplyError, .writeFailed) }
        let saved = try await repository.cached()
        XCTAssertEqual(saved, cache.old)
    }
}

Подтверждение обновления связано с записью. Новый remote не становится ложным устойчивым успехом при отказе cache.

import XCTest
// FeatureSupport.swift, ControlledSupplyRemote.swift и слои из урока.
final class LatestTests: XCTestCase {
    @MainActor func testLatestResponseWins() async throws {
        let cache = MemorySupplyCache()
        let remote = ControlledSupplyRemote()
        let model = SupplyModel(repository: SupplyRepository(
            cache: cache, remote: remote
        ))
        let first = Task { await model.refresh() }
        await remote.waitForRequests(1)
        let second = Task { await model.refresh() }
        await remote.waitForRequests(2)
        let latest = [Supply(id: 11, title: "Чай", count: 3)]
        await remote.finish(1, items: latest)
        await second.value
        await remote.finish(0, items: [Supply(id: 11, title: "Чай", count: 1)])
        await first.value
        XCTAssertEqual(model.state.items, latest)
        XCTAssertEqual(cache.items, latest)
        XCTAssertFalse(model.state.isLoading)
        XCTAssertNil(model.state.error)
    }
}

Детерминированная проверка разделяет очередность завершения и актуальность. Старый запрос не меняет ни сохранённую копию, ни состояние интерфейса.
